"""
Threat Hunting Baseline Tools (Demo-only, local-only).

Compute simple baseline features for a seed entity and detect deviations in a hunt window.
Designed for clarity and explainability (2–4 flags max).
"""

from __future__ import annotations

from collections import Counter
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

from .threat_hunting_data_tools import _get_nested, _parse_ts, read_events, load_threat_hunting_dataset


def _hour_bucket(ts: str) -> str:
    dt = _parse_ts(ts)
    return f"{dt.hour:02d}"


def _top_n(counter: Counter, n: int) -> List[Dict[str, Any]]:
    return [{"key": k, "count": v} for k, v in counter.most_common(n)]


def _safe_mean(values: List[int]) -> float:
    return sum(values) / len(values) if values else 0.0


def _safe_std(values: List[int]) -> float:
    if len(values) < 2:
        return 0.0
    mu = _safe_mean(values)
    var = sum((x - mu) ** 2 for x in values) / (len(values) - 1)
    return var ** 0.5


def compute_baseline_features(
    entity_username: str,
    history_start_ts: str,
    history_end_ts: str,
    dataset_root: str = "data/threat_hunting_demo",
) -> Dict[str, Any]:
    """
    Compute baseline features for an entity from auth and cloud audit events.
    """
    try:
        ds = load_threat_hunting_dataset(dataset_root)
        if not ds["success"]:
            return ds
        tables = ds["data"]["tables"]
        auth_path = tables.get("auth_events") or str(Path(dataset_root) / "canonical" / "auth_events.jsonl")
        cloud_path = tables.get("cloud_audit_events") or str(Path(dataset_root) / "canonical" / "cloud_audit_events.jsonl")

        auth = read_events(auth_path, history_start_ts, history_end_ts, {"user.name": entity_username}, limit=100000)
        cloud = read_events(cloud_path, history_start_ts, history_end_ts, {"user.name": entity_username}, limit=100000)

        auth_events = auth.get("data", {}).get("events", []) if auth.get("success") else []
        cloud_events = cloud.get("data", {}).get("events", []) if cloud.get("success") else []

        hours = Counter()
        hosts = Counter()
        methods = Counter()
        regions = Counter()

        for e in auth_events:
            ts = e.get("@timestamp")
            if ts:
                hours[_hour_bucket(ts)] += 1
            h = _get_nested(e, "host.name")
            if h:
                hosts[str(h).lower()] += 1
            m = _get_nested(e, "authentication.method")
            if m:
                methods[str(m).lower()] += 1

        for e in cloud_events:
            r = _get_nested(e, "cloud.region")
            if r:
                regions[str(r).lower()] += 1

        # Daily auth counts (for spike detection)
        per_day = Counter()
        for e in auth_events:
            ts = e.get("@timestamp")
            if not ts:
                continue
            dt = _parse_ts(ts)
            per_day[dt.date().isoformat()] += 1
        daily_counts = [per_day[d] for d in sorted(per_day.keys())]

        return {
            "success": True,
            "message": "Computed baseline features",
            "data": {
                "entity": entity_username,
                "window": {"start_ts": history_start_ts, "end_ts": history_end_ts},
                "features": {
                    "login_hours_top": _top_n(hours, 3),
                    "hosts_top": _top_n(hosts, 5),
                    "auth_methods_top": _top_n(methods, 3),
                    "cloud_regions_top": _top_n(regions, 3),
                    "daily_auth_counts": daily_counts,
                    "daily_auth_mean": round(_safe_mean(daily_counts), 2),
                    "daily_auth_std": round(_safe_std(daily_counts), 2),
                    "unique_hosts": len(hosts),
                },
                "evidence": {
                    "auth": auth.get("data", {}).get("evidence", []),
                    "cloud": cloud.get("data", {}).get("evidence", []),
                },
            },
        }
    except Exception as e:
        return {"success": False, "message": f"Error computing baseline features: {e}", "data": None}


