def _flag(flag_type: str, why: str, evidence: List[Dict[str, Any]], confidence: str) -> Dict[str, Any]:
    return {
        "flag_type": flag_type,
        "why": why,
        "confidence": confidence,
        "evidence": evidence[:5],  # keep tight for demo
    }


def detect_deviations(
    baseline: Dict[str, Any],
    recent: Dict[str, Any],
    policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Compare recent activity against baseline and output 2–4 deviations max.
    """
    try:
        policy = policy or {}
        max_flags = int(policy.get("max_flags", 4))
        min_flags = int(policy.get("min_flags", 2))

        base_f = baseline.get("data", {}).get("features", {})
        recent_f = recent.get("data", {}).get("features", {})

        base_hosts = {x["key"] for x in base_f.get("hosts_top", [])}
        recent_hosts = {x["key"] for x in recent_f.get("hosts_top", [])}
        new_hosts = sorted(list(recent_hosts - base_hosts))

        base_hours = {x["key"] for x in base_f.get("login_hours_top", [])}
        recent_hours = {x["key"] for x in recent_f.get("login_hours_top", [])}
        abnormal_hours = sorted(list(recent_hours - base_hours))

        base_methods = {x["key"] for x in base_f.get("auth_methods_top", [])}
        recent_methods = {x["key"] for x in recent_f.get("auth_methods_top", [])}
        new_methods = sorted(list(recent_methods - base_methods))

        flags: List[Dict[str, Any]] = []

        # Evidence (use the recent auth evidence pointers primarily)
        recent_auth_evidence = recent.get("data", {}).get("evidence", {}).get("auth", [])

        if new_hosts:
            flags.append(
                _flag(
                    "NEW_HOST",
                    f"Observed login activity from host(s) not present in baseline top hosts: {', '.join(new_hosts[:3])}.",
                    recent_auth_evidence,
                    "high",
                )
            )

        if abnormal_hours:
            flags.append(
                _flag(
                    "ABNORMAL_TIME",
                    f"Observed login hour bucket(s) outside baseline norms: {', '.join(abnormal_hours[:4])} UTC.",
                    recent_auth_evidence,
                    "medium",
                )
            )

        if new_methods:
            flags.append(
                _flag(
                    "NEW_AUTH_METHOD",
                    f"Observed authentication method(s) not seen in baseline: {', '.join(new_methods[:3])}.",
                    recent_auth_evidence,
                    "medium",
                )
            )

        # Spike (simple): recent auth count > baseline mean + 2*std * (window_days factor)
        mean = float(base_f.get("daily_auth_mean", 0))
        std = float(base_f.get("daily_auth_std", 0))
        recent_count = int(recent_f.get("auth_event_count", 0))
        threshold = mean + 2 * std
        if std == 0 and mean > 0:
            threshold = mean * 2.5
        if recent_count > max(3, int(threshold)):
            flags.append(
                _flag(
                    "AUTH_SPIKE",
                    f"Authentication volume in the window ({recent_count}) exceeds baseline expectation (≈{mean}+2σ).",
                    recent_auth_evidence,
                    "low",
                )
            )

        # Enforce demo constraints: 2–4 flags max, stable ordering
        preferred_order = ["NEW_HOST", "ABNORMAL_TIME", "NEW_AUTH_METHOD", "AUTH_SPIKE"]
        flags.sort(key=lambda f: preferred_order.index(f["flag_type"]) if f["flag_type"] in preferred_order else 999)

        if len(flags) > max_flags:
            flags = flags[:max_flags]

        # If we have too few flags, that's ok for real life, but demo requires 2.
        # Pad with an analyst-style "no further deviation detected" is not helpful; instead allow <2.
        if len(flags) < min_flags:
            # Keep behavior honest: do NOT fabricate flags.
            pass

        return {
            "success": True,
            "message": f"Detected {len(flags)} deviation flag(s)",
            "data": {"flags": flags, "constraints": {"max_flags": max_flags, "min_flags": min_flags}},
        }
    except Exception as e:
        return {"success": False, "message": f"Error detecting deviations: {e}", "data": None}

